async function runAlgorithmProgram(args,{stayOnBoard=false}={}){
 if(working)throw Error('目前運算尚未結束');
 if(!isTauri())throw Error('可編程算法使用桌面 Python 執行器，請在桌面版執行');
 working=true;render();status('正在執行算法程式並保存實算圖…');
  try{const captured=await prepareHistoryCapture({label:args.title||'算法程式實算',type:'program'});let started=false,run,nativeResponse,executedRequest;try{run=await runAlgorithm(project,args,async request=>{started=true;executedRequest=request;if(request.nativePipeline){nativeResponse=await invoke('execute_native_pipeline',{request:{image:request.nativePipeline.image[0],plan:request.nativePipeline.plan,planFingerprint:request.runtimePlan?.fingerprint||'native-plan',pixelFingerprint:request.nativePipeline.image[0].sourceSha256,inputIdentity:request.sourceBinding?.images?.[0]||{imageId:request.nativePipeline.image[0].id},}});return adaptNativePipelineResponse(nativeResponse,request);}nativeResponse=await invoke('execute_cv_algorithm',{request});return nativeResponse;});await trialHistory.finish(captured,{run});}catch(error){if(started){const observed=nativeResponse?.runId?{...nativeResponse,schema:'agentcv-algorithm-run-1',title:args.title,code:args.code,parameters:executedRequest.parameters,sourceBinding:executedRequest.sourceBinding,justification:executedRequest.justification,expectedOutputs:executedRequest.expectedOutputs,historyApplication:'NOT_APPLIED',historyApplicationReason:String(error?.message||error)}:null;await trialHistory.finish(captured,{run:observed,error});}throw error;}
  planView.close?.();planView.explanation?.close?.();pipelineView.closeEvidence?.();pipelineView.dialog?.close();
  const display=defaultAlgorithmPresentation(run);if(!stayOnBoard){if(display){proposeAlgorithmPresentation(project,{run_id:run.runId,presentation_json:JSON.stringify(display)});page=6;}else algorithmView.open(run);}status(run.status==='SUCCEEDED'?'程式已實算；可看中間圖、節點文檔與完整程式。':'程式未完成；已保存錯誤、原始程式與部分產物，可讓 螃蟹 修正重試。');return run;
 }finally{working=false;render();}
}
let inspectionAbortController=null;
function cancelInspectionExecution(){
 if(!inspectionAbortController)return false;
 inspectionAbortController.abort();
 status('停止中 · 目前節點結束後停止，不再執行後續節點或工件');
 project.event('inspection_stop_requested');
 return true;
}
installInspectionStopShortcut(cancelInspectionExecution);
let inspectionReadGeneration=0;
async function hydrateInspectionRuns(runs,reference,assertCurrent=()=>{}){
 if(!reference)return runs;
 for(const run of runs)for(const artifact of run.artifacts||[])if(artifact.type==='image'&&artifact.pixelRetention!=='metadata-only'&&!artifact.dataURL&&!artifact.dataUrl){assertCurrent();const loaded=await inspectionRecords.artifact({...reference,runId:run.runId,artifactId:artifact.id});assertCurrent();project.setInspectionArtifactPreview(run.runId,artifact.id,loaded.dataURL);}
 return runs;
}
async function openInspectionUnit(reference){
 const generation=++inspectionReadGeneration,epoch=project.epoch,data=project.data,assertCurrent=()=>{if(generation!==inspectionReadGeneration||project.epoch!==epoch||project.data!==data)throw Error('已切換專案或選擇其他工件；舊單件讀取未覆蓋目前畫板。');};
 const saved=await inspectionRecords.read(reference);assertCurrent();const runs=project.restoreInspectionUnit(saved,reference),imageId=saved.record.imageIds?.[0];assertCurrent();if(imageId&&project.imageRecord(imageId)&&project.image?.id!==imageId){await project.selectImage(imageId);assertCurrent();}await hydrateInspectionRuns(runs,reference,assertCurrent);assertCurrent();render();return {...saved,runs};
}
