async function next(){if(working)return;if(project.data.activeAlgorithmPresentationId&&page===6)return go(7);if(project.data.activeAlgorithmPresentationId&&page===7)throw Error('程式方案仍是試算；尚未完成獨立圖片集驗證，不能發布');if(page===1){ensureProfile();return go(2)}if(page===2)return go(3);if(page===3){if(!project.getRegion(wf().workpiece.id)){const c=board.suggestions.find(c=>c.id===board.suggestedId);if(!c)throw Error('請選候選或圈定工件');assertCurrentCandidate(c,wf().workpiece.id);project.setRegion(wf().workpiece.id,c.points,project.image.id,candidateSource(c))}return go(4)}if(page===4)return go(5);if(page===5){project.buildRecipe();return go(6)}if(page===6){if(wf().pipelinePlan)return batchGoalPipeline();await go(7);return validateAll()}if(page===7){project.publish();status('已凍結並發布目前配方；修改依賴會使此發布失效');render()}}
let canvasImportTarget=null;
let referenceImportPending=false;
function folderImportPrompt(folderName){
 return new Promise(resolve=>{
  const d=document.createElement('dialog');d.className='folder-import-choice';d.setAttribute('aria-label','文件夾導入方式');
  const title=document.createElement('h2');title.textContent='已選擇圖片文件夾';
  const note=document.createElement('p');note.textContent=`「${folderName||'未命名文件夾'}」包含多張圖片，請選擇導入方式。`;
  const actions=document.createElement('div');actions.className='folder-import-choice-actions';
  const finish=choice=>{d.close();d.remove();resolve(choice)};
  for(const [choice,label,cls] of [['cancel','取消導入','danger'],['classify','以文件夾名稱作為分類導入','primary'],['agent','對話 Agent','primary'],['defer','只導入圖片，稍後處理','']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.className=cls;b.onclick=()=>finish(choice);actions.append(b)}
  d.append(title,note,actions);d.addEventListener('cancel',e=>{e.preventDefault();finish('cancel')},{once:true});document.body.append(d);d.showModal();
 });
}
function folderClassificationDecisions(task,folderName){
 const decisions={};
 for(const group of task.structure.groups){const parts=String(group.path||'').split('/').filter(Boolean);const category=parts.length>1?parts[1]:folderName;if(category)decisions[group.id]={category,quality:/^(ok|good|良品)$/i.test(category)?'OK':/^(ng|bad|fail|不良|未焊)$/i.test(category)?'NG':undefined};}
 return decisions;
}
async function importImages(folder,sourceId,boardId){if(sourceId)canvasImportTarget={sourceId,boardId};if(working)return;const imported=isTauri()?await invoke('import_dataset_images',{folder}):null;const files=imported?.images||null;if(!isTauri()){(folder?$('browserFolder'):$('browserImages')).click();return}if(!files?.length)return;const folderName=imported.fileStructure?.find?.(entry=>entry.kind==='directory')?.path?.split?.('/')[0]||files[0]?.sourceRelativePath?.split?.('/')[0]||'圖片文件夾';const choice=folder?await folderImportPrompt(folderName):'agent';if(choice==='cancel')return;await addImages(files,imported.fileStructure,{showManager:choice==='agent',folderClassification:choice==='classify',autoAnalyze:choice==='agent'})}
async function addImages(files,fileStructure,{showManager=false,folderClassification=false,autoAnalyze=true}={}){
 working=true;const destination=canvasImportTarget;canvasImportTarget=null;const before=new Set(project.data.images.map(i=>i.id));
 try{
  const home=projectCanvasHome(),targetBoard=project.ensureInquiry().boards.find(b=>b.id===(destination?.boardId||home.board.id)),source=targetBoard.projectSpaces.sources.find(x=>x.id===(destination?.sourceId||home.source.id));
  await project.addImages(files.map(file=>({...file,sourceId:source.id})),decode);
  const added=project.data.images.filter(image=>!before.has(image.id));project.bindCanvasImages(targetBoard.id,source.id,[...new Set([...source.imageIds,...added.map(image=>image.id)])]);
  if(added.length){await project.selectImage(added[0].id);let sourceProfile=source.profileId||source.imageIds.map(id=>project.imageRecord(id)?.profileId).find(Boolean);if(!sourceProfile)sourceProfile=project.setProfile({name:source.title+' · 成像配置',width:added[0].width,height:added[0].height}).id;project.updateCanvasSpace(targetBoard.id,source.id,{profileId:sourceProfile});project.assignProfiles(added.map(image=>image.id),sourceProfile);}
  const managerTask=added.length?imageManager.enqueue(source.id,added,fileStructure,{open:showManager,autoAnalyze}):null;
  if(managerTask&&folderClassification){const task=imageManagerTasks(project,source.id).find(t=>t.id===managerTask);if(task){const decisions=folderClassificationDecisions(task,folderNameFromStructure(fileStructure));confirmImportMeaning(project,managerTask,decisions,{applyLabels:true});}}
  page=6;board.imageId=null;status(managerTask?(imageManager.task(managerTask).status==='FAILED'?'圖片已加入；目錄分析未啟動，請點來源卡的「分析失敗」查看原因。':'圖片已加入；圖像管理員正在整理目錄含義，進度顯示在來源卡。'):'圖片索引已加入圖像源。');
 }finally{working=false;render();inquiryView.fit();}
}

function folderNameFromStructure(fileStructure=[]){return fileStructure.find?.(entry=>entry.kind==='directory')?.path?.split?.('/')[0]||'圖片文件夾'}

function readData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function importReferences(referenceId,boardId,droppedFiles,onReading){
 if(referenceImportPending)throw Error('正在加入資料，請稍候再試');
 referenceImportPending=true;
 try{
  const epoch=project.epoch,home=referenceId?null:projectCanvasHome(),targetBoard=boardId||home?.board.id,targetSpace=referenceId||home?.reference.id;
  let records;
  if(droppedFiles)records=await readReferenceFiles(droppedFiles,{readData,onReading});
  else if(isTauri()){records=(await invoke('import_references')||[]).map(f=>({...f,type:f.mime?.startsWith('text/')?'text':'attachment',extractedText:f.text||undefined}));if(records.length)onReading?.();}
  else records=await readReferenceFiles(await chooseReferenceFiles($('browserReferences')),{readData,onReading});
  if(!records.length)return {count:0,cancelled:true};
  if(project.epoch!==epoch)throw Error('專案已切換，這批資料未加入；請在目前專案重新選取');
  const imported=project.importCanvasReferences(targetBoard,targetSpace,records);render();
  return {count:imported.length,referenceIds:imported.map(record=>record.id)};
 }finally{referenceImportPending=false}
}
