let commandSuggestionIndex=-1;
function commandSuggestionEntries(){
 const dynamic=(agent.availableCommands||[]).map(item=>{const name=typeof item==='string'?item:item?.name;return name?['/'+String(name).replace(/^\//,''),item.description||item.title||'執行器命令']:null}).filter(Boolean);
 const seen=new Set(),entries=[];for(const [value,label] of [...builtinChatCommands,...dynamic])if(!seen.has(value)){seen.add(value);entries.push({value,label});}return entries;
}
function renderCommandSuggestions(){
 const box=$('commandSuggestions'),input=$('chatInput');if(!box||!input)return;
 const raw=input.value,trimmed=raw.trimStart();if(!trimmed.startsWith('/')){box.hidden=true;commandSuggestionIndex=-1;return;}
 const token=trimmed.split(/\s+/,1)[0].toLowerCase(),hasSpace=/^\/\S+\s/.test(trimmed);
 const query=hasSpace?trimmed.toLowerCase():token;
 let entries=commandSuggestionEntries().filter(item=>item.value.toLowerCase().startsWith(query));
 if(hasSpace&&token==='/goal')entries=commandSuggestionEntries().filter(item=>item.value.toLowerCase().startsWith('/goal '));
 if(!entries.length){box.hidden=true;commandSuggestionIndex=-1;return;}
 commandSuggestionIndex=Math.max(0,Math.min(commandSuggestionIndex,entries.length-1));box.replaceChildren();
 entries.slice(0,8).forEach((item,index)=>{const button=el('button',undefined,'command-suggestion');button.type='button';button.setAttribute('role','option');button.setAttribute('aria-selected',String(index===commandSuggestionIndex));button.append(el('code',item.value),el('span',item.label));button.onmousedown=event=>{event.preventDefault();chooseCommandSuggestion(item)};box.append(button)});box.hidden=false;
}
